module cpu_datapath(clk, rst, instr, acc, pc);
  input        clk;
  input        rst;
  input  [7:0] instr;
  output [7:0] acc;
  output [3:0] pc;

  reg [7:0] acc_reg;
  reg [3:0] pc_reg;

  wire [1:0] opcode;
  wire [7:0] operand;

  assign opcode  = instr[7:6];
  assign operand = {2'b00, instr[5:0]};

  assign acc = acc_reg;
  assign pc  = pc_reg;

  always @(posedge clk) begin
    if (rst) begin
      acc_reg <= 8'h00;
      pc_reg  <= 4'h0;
    end else begin
      case (opcode)
        2'b00: begin
          acc_reg <= operand;          // load immediate
        end

        2'b01: begin
          acc_reg <= acc_reg + operand; // add immediate
        end

        2'b10: begin
          acc_reg <= acc_reg - operand; // subtract immediate
        end

        2'b11: begin
          acc_reg <= acc_reg;           // branch/control instruction, accumulator unchanged
        end
      endcase

      if ((opcode == 2'b11) && (acc_reg != 8'h00))
        pc_reg <= instr[3:0];           // branch if accumulator non-zero
      else
        pc_reg <= pc_reg + 4'd1;        // next instruction
    end
  end

endmodule

